mapper.select:
SELECT id, user_id, session_id, task_type, status, content, result, error_message, created_at, updated_at, completed_at
FROM memory_task
WHERE id = #{id}

SELECT id, user_id, session_id, task_type, status, content, result, error_message, created_at, updated_at, completed_at
FROM memory_task
WHERE user_id = #{userId}
ORDER BY updated_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM memory_task
WHERE user_id = #{userId}

SELECT id, user_id, session_id, task_type, status, content, result, error_message, created_at, updated_at, completed_at
FROM memory_task
WHERE user_id = #{userId} AND status = #{status}
ORDER BY updated_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM memory_task
WHERE user_id = #{userId} AND status = #{status}

mapper.update:
UPDATE memory_task
SET status = #{status}, updated_at = NOW()
WHERE id = #{id}
